const body = $input.first().json.body || $input.first().json;
const allowedRules = new Set(['510120', '510121', '510122', '510130', '510131', '510132']);
const ruleId = String(body?.rule?.id || '');
const level = Number(body?.rule?.level || 0);
const groups = Array.isArray(body?.rule?.groups) ? body.rule.groups : [];
const rawUser = String(
  body?.data?.win?.eventdata?.targetUserName ||
  body?.data?.win?.eventdata?.subjectUserName ||
  body?.data?.srcuser || ''
).trim();
const username = rawUser.replace(/^.*\\/, '').replace(/@.*$/, '');
const srcIp = String(
  body?.data?.win?.eventdata?.ipAddress ||
  body?.data?.srcip ||
  body?.data?.src_ip || ''
).trim();
const isIPv4 = (value) => /^(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}$/.test(value);
const protectedAccounts = new Set(['administrator', 'admin', 'guest', 'krbtgt', 'wazuh', 'splunk', 'thehive', 'n8n', 'root']);
const controlledSimulationSource = srcIp === '10.10.3.3';
let skipReason = '';
if (!allowedRules.has(ruleId)) skipReason = `unsupported brute-force rule: ${ruleId || 'missing'}`;
else if (level < 10) skipReason = `rule level below threshold: ${level}`;
else if (!username || username.endsWith('$') || protectedAccounts.has(username.toLowerCase())) skipReason = 'protected, machine, or missing account';
else if (!isIPv4(srcIp)) skipReason = 'missing or invalid source IPv4 address';
const eventId = String(body?.data?.win?.system?.eventRecordID || body?.data?.win?.system?.eventRecordId || body?.id || body?.timestamp || Date.now());
const sourceRef = `wazuh-brute-v2-${ruleId}-${eventId}`;
return [{json:{
  skip: Boolean(skipReason),
  skip_reason: skipReason,
  rule_id: ruleId,
  rule_level: level,
  rule_desc: String(body?.rule?.description || 'Brute-force detection'),
  groups,
  username,
  src_ip: srcIp,
  agent_name: String(body?.agent?.name || 'unknown'),
  agent_id: String(body?.agent?.id || ''),
  event_id: eventId,
  timestamp: String(body?.timestamp || new Date().toISOString()),
  source_ref: sourceRef,
  controlled_simulation_source: controlledSimulationSource,
  scenario: 'BRUTE_FORCE'
}}];

const alert = $('Normalize & Safety Gate').item.json;
const counter = Number(Object.values($input.first().json)[0]);
if (!Number.isInteger(counter) || counter < 1) throw new Error('Redis did not return a valid deduplication counter');
return [{json:{...alert,dedup_count:counter,is_duplicate:counter > 1}}];

const d = $input.first().json;
const isCompromise = d.rule_id === '510132';
const title = isCompromise
  ? `[CRITICAL] Possible account compromise: ${d.username} after brute force from ${d.src_ip}`
  : `[REVIEW REQUIRED] Brute Force: ${d.username} from ${d.src_ip}`;
const severity = isCompromise ? 4 : 3;
const body = {
  title,
  description: [
    'Brute-force activity requires analyst approval before containment.',
    `Rule: ${d.rule_id} - ${d.rule_desc}`,
    `Agent: ${d.agent_name}`,
    `Target account: ${d.username}`,
    `Source IP: ${d.src_ip}`,
    `Dedup count: ${d.dedup_count}`,
    'Automated account disablement is deliberately disabled.'
  ].join('\n'),
  type: 'external',
  source: 'wazuh-n8n-soar',
  sourceRef: d.source_ref,
  severity,
  tlp: 2,
  tags: ['brute_force', 'T1110', 'approval_required', d.agent_name]
};
return [{json:{...d,_hive_body:JSON.stringify(body)}}];

const d = $('Build TheHive Alert').item.json;
const hive = $input.first().json;
const hiveId = hive?._id || hive?.id;
if (!hiveId) throw new Error('TheHive did not return an alert ID; approval request not sent');

function isIPv4(value) {
  return typeof value === 'string' && /^(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}$/.test(value);
}
function isEligibleAccountName(value) {
  if (typeof value !== 'string' || !/^[A-Za-z][A-Za-z0-9._-]{0,63}$/.test(value)) return false;
  const name = value.toLowerCase();
  return !['administrator', 'admin', 'guest', 'krbtgt', 'wazuh', 'splunk', 'thehive', 'n8n', 'root'].includes(name) && !name.startsWith('svc_');
}

const allowBlockIp = d.controlled_simulation_source === true && isIPv4(d.src_ip);
const validTargetAccount = isEligibleAccountName(d.username);
const routinePolicy = {
  allow_block_ip: allowBlockIp,
  allow_disable_account: validTargetAccount,
  account_disable_mode: 'eligible_group',
  allow_human_approved_exception: false,
  allow_isolate_host: false,
};
const exceptionPolicy = {
  allow_block_ip: false,
  allow_disable_account: validTargetAccount,
  account_disable_mode: 'human_approved_exception',
  allow_human_approved_exception: true,
  human_approval_required: true,
  allow_isolate_host: false,
};
const baseContext = {
  alert_id:hiveId,
  rule_id:d.rule_id,
  scenario:d.scenario,
  confidence:100,
  tier:'human_approval_required',
  auto_candidate:false,
  src_ip:d.src_ip,
  dest_ip:'',
  username:d.username,
  agent_name:d.agent_name,
  agent_id:d.agent_id,
  recommended_actions:[
    'Validate failed-logon volume and affected account',
    'Review source history in Splunk and Wazuh',
    'Use the routine path only for SOC-SOAR-Disable-Eligible members',
    'Use the exception path only for a named account after analyst containment approval'
  ].join('|'),
};
const routineContext = {
  ...baseContext,
  ioc_to_block: allowBlockIp ? d.src_ip : '',
  accounts_to_disable: validTargetAccount ? d.username : '',
  action_policy: routinePolicy,
};
const exceptionContext = {
  ...baseContext,
  ioc_to_block: '',
  accounts_to_disable: validTargetAccount ? d.username : '',
  action_policy: exceptionPolicy,
};
const routineValue = JSON.stringify(routineContext);
const exceptionValue = JSON.stringify(exceptionContext);
const policyLines = [
  allowBlockIp
    ? '*Routine IP action after approval:* add the controlled simulation IP ' + d.src_ip + ' to SOC_BRUTE_BLOCK.'
    : '*Routine IP action:* none. The source is not the controlled test IP.',
  validTargetAccount
    ? '*Routine account action after approval:* disable ' + d.username + ' only after SOC-SOAR-Disable-Eligible verification.'
    : '*Routine account action:* none. The account name fails the automation safety checks.',
  validTargetAccount
    ? '*Exception account action:* a separate named-account approval can disable only ' + d.username + '; protected, privileged, service, ambiguous, and already-disabled accounts are refused.'
    : ''
].filter(Boolean);
const actions = [
  {type:'button',style:'primary',text:{type:'plain_text',text:'Approve Routine Actions'},action_id:'approve_all',value:routineValue},
  {type:'button',style:'danger',text:{type:'plain_text',text:'Approve Account Disable (Exception)'},action_id:'approve_exception',value:exceptionValue},
  {type:'button',style:'danger',text:{type:'plain_text',text:'Reject'},action_id:'reject',value:routineValue},
  {type:'button',text:{type:'plain_text',text:'Investigate First'},action_id:'investigate',value:routineValue}
];
const blocks = [
  {type:'header',text:{type:'plain_text',text:'ACTION REQUIRED: ' + d.scenario,emoji:true}},
  {type:'section',text:{type:'mrkdwn',text:'*' + d.rule_desc + '*\nTarget account: ' + d.username + '\nSource IP: ' + d.src_ip + '\n\n' + policyLines.join('\n')}},
  {type:'actions',block_id:'soar_approval_actions_v3',elements:actions}
];
return [{json:{...d,_hive_id:hiveId,_approval_payload:JSON.stringify({channel:'C0SLACKCHANNEL',text:'Approval required: brute-force activity on ' + d.agent_name,blocks})}}];

const d = $('Build Approval Request').item.json;
const slack = $input.first().json;
return [{json:{
  status:'approval_requested',
  scenario:d.scenario,
  source_ref:d.source_ref,
  thehive_alert_id:d._hive_id,
  approval_message_posted:slack?.ok === true,
  action_policy:'account disable is disabled; only a controlled source IP may be considered after approval',
  timestamp:new Date().toISOString()
}}];
